import{_ as t,a,b as l,c as o,d as i,e as s,f as n,g as m}from"./chunks/a37af272e9c4c5b4cf1d.CvIkSzP-.js";import{_ as h,C as c,o as g,c as u,j as e,a as d,E as _,a6 as f}from"./chunks/framework.CnPv4DE1.js";const O=JSON.parse('{"title":"作为创作者,如何逃出新手地狱","description":"","frontmatter":{"title":"作为创作者,如何逃出新手地狱","originalTitle":"How To Escape Beginner Hell As A Creator","date":"2025-01-25","originalUrl":"https://thedankoe.com/letters/how-to-escape-beginner-hell-as-a-creator/","minutes":21,"sourceHash":"b51b5fa20a97e2527a0e9cc54ddd1a62020e2a29ca96eda3e705718f05875e59","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-escape-beginner-hell-as-a-creator/"}]]},"headers":[],"relativePath":"letters/how-to-escape-beginner-hell-as-a-creator.md","filePath":"letters/how-to-escape-beginner-hell-as-a-creator.md"}'),b={name:"letters/how-to-escape-beginner-hell-as-a-creator.md"};function k(T,p,x,P,w,q){const r=c("ArticleMeta");return g(),u("div",null,[p[0]||(p[0]=e("h1",{id:"作为创作者-如何逃出新手地狱",tabindex:"-1"},[d("作为创作者,如何逃出新手地狱 "),e("a",{class:"header-anchor",href:"#作为创作者-如何逃出新手地狱","aria-label":'Permalink to "作为创作者,如何逃出新手地狱"'},"​")],-1)),_(r),p[1]||(p[1]=f('<p><a href="https://www.youtube.com/embed/REwaFvbelEk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>3到6个月。</p><p>这就是大多数创作者被困在新手地狱里的时长。</p><p>你知道的,那个可怕的地方,你觉得自己完全不知道自己在干什么。你开始怀疑坚持下去到底值不值得。你在想接下来该试什么新东西(结果只是重蹈覆辙)。不幸的是,大多数人在事情开始好转之前就已经放弃了。</p><p>但请理解这一点:</p><p>大多数人认为答案是「保持坚持就好」。</p><p>即使你没有任何进展,也要硬着头皮继续推进。</p><p>零点赞。零粉丝。零销售。这是世界上最痛苦的事情之一。成为一名创作者本应是你通往美好生活的门票,不是吗?还是说这一切只是一场骗局?一个被营销人员和大师们卖给你的空想?</p><p>这里有一个残酷的真相……<em>你没有进展,是因为你做的事情本身就不对。</em></p><p>所以,在你回到那个你曾誓言要离开的舒适生活之前,先听我说几句。</p><p>你需要到达那个万事「咔哒一声就通了」的时刻。你需要那个「啊哈!」的瞬间,清晰感突然降临,你确切地知道该如何突破到进阶天堂。</p><p>我知道你现在正站在崩溃的边缘。</p><p>但请记住你为什么开始。</p><p>你知道自己想做一些有创造性的事情。</p><p>你知道要做到这一点,你需要在工作之外拥有自己的受众。</p><p>你知道你想掌控自己赚的钱,以及自己设计的生活方式。</p><p>你知道,要做到这些,你必须写作或创作。你需要成为自己的媒体公司,把人们吸引到你独立完成的作品上来。你的自出版书籍。你的音乐。你的想法。你的专业知识。</p><p>你只需要到达那个光荣的瞬间——那个「咔哒一声」——你就终于会感觉到自己掌控了自己的未来。</p><p>让我来帮你。</p><h2 id="如何逃出新手地狱" tabindex="-1">如何逃出新手地狱 <a class="header-anchor" href="#如何逃出新手地狱" aria-label="Permalink to &quot;如何逃出新手地狱&quot;">​</a></h2><blockquote><p>所有的一夜成名,都花了大约十年。——杰夫·贝索斯(Jeff Bezos)</p></blockquote><p>现在,有一系列的行动可以带来成果。</p><p>简单明了。</p><p>但大多数创作者只是机械地照搬他们在某个视频、课程或文章里得到的指令。</p><p>我的朋友,这不是一份有着线性步骤的工作,让你可以每天照本宣科、关闭大脑、像以前那样过日子。这是一个一人企业。你是CEO。你是CMO。你是COO。你就是一切。请开始像这样去行动。振作起来。</p><p>我知道这一点,因为我曾在新手地狱里困了将近5年。</p><p>我在代发货、3家电商店铺、数字艺术与摄影、一家Facebook广告代理公司、一家SEO内容代理公司之间反复跳跃,最后不得不去做一份网页设计的工作,因为贷款越堆越高,而我已经不愿意再继续溺水下去了。</p><p>在那份工作里,我拖延着所有的正职工作,只为了去接自由职业网页设计的活儿。当我开始在社交媒体上写作以吸引更多客户时,我并没有经历新手地狱,因为我早已知道如何避开它。</p><p>我一路上学到的技能,最终促成了我自己的那次「咔哒一声」。我会告诉你这些技能是什么,它们包括:</p><ul><li>一种不同的思考方式来寻找你的细分领域</li><li>吸引粉丝的最佳内容类型</li><li>如何在不依赖平台广告收益的情况下实现变现</li><li>为什么你应该忘掉搭建销售漏斗这件事,因为社交媒体已经变了</li></ul><p>还有更多,我就留给你自己去想象了。我打算给你一个浓缩版的社交媒体大师课,让你终于能感觉到自己掌控了自己的毕生事业。我要告诉你,如何变成这样的人:</p><p><img src="'+t+'" alt=""></p><p>在教过近3万名学生写作和内容创作之后,以下是7条会彻底改变你的技巧、策略和洞见:</p><h3 id="_1-做那些对新手真正有效的事" tabindex="-1">1) 做那些对新手真正有效的事 <a class="header-anchor" href="#_1-做那些对新手真正有效的事" aria-label="Permalink to &quot;1) 做那些对新手真正有效的事&quot;">​</a></h3><p>新手地狱可以持续从3个月到30年不等。</p><p>对某些人来说,它会持续一生(那些饥饿的艺术家们)。</p><p>为什么?</p><p>因为新手没有意识到,高阶创作者现在所做的事情,<em>并不是</em>他们当初赖以起步、实现增长的那些事。</p><p>这也是这封信里最重要的一点:</p><p><em>你没有增长,是因为你没有在做那些能带来增长的事。</em></p><p>新手们开始发一些哲理语录,或者试图成为下一个马可·奥勒留(Marcus Aurelius),可这时候根本没人知道他们是谁,也没人在乎他们做的事。他们没有任何<em>权威性</em>。</p><p>很抱歉要打破你的幻想,但你不是罗马皇帝。</p><p>你不会被人尊重,因为根本没人知道你是谁。</p><p>这意味着,你必须先在社交媒体上<em>建立起权威</em>,人们才会在意你那可爱的小幸运饼签式的帖子。</p><p>你要如何建立权威?</p><p><strong>1 – 解决更多的问题。</strong></p><p>作为新手,你80%的内容都应该从一个痛点开始。</p><p>如果你只是随手写点想法而不加任何深思,那你走不了多远。刚起步时,你需要对帖子的结构非常讲究。</p><p>每当你想写一个想法时,先想一想普通人会面对的一个痛点。让你的内容从那里开始。</p><p>使用这样的句式:</p><ul><li><strong>「大多数人」</strong>——比如:大多数人写作很烂。</li><li><strong>「如果你在……上遇到困难」</strong>——比如:如果你难以集中注意力超过5分钟。</li><li><strong>「最糟糕的」</strong>——比如:你能学的最糟糕的技能就是网页设计。</li></ul><p>我在自己的内容里经常用这些句式,因为<em>它们真的有效。</em></p><p>问题能抓住注意力。问题能打开一个好奇心的循环。问题能让帖子接下来的部分变得100倍更有影响力。</p><p>从问题开始,然后用一份步骤清单、你独到的观点,或一个新颖的洞见来收尾。</p><p><strong>2 – 极度深入地覆盖最重要的那些想法。</strong></p><p>一旦你选定了一个主题,你不能就这样随意地写一些零散的想法。</p><p>在那个主题之下,总有那么几个精选出来的常青想法,<em>永远</em>表现良好。你要做的,就是找到它们,并以<em>你自己的品牌</em>把关于它们能写的一切都写出来。</p><p>以创业为例,那些想法就是:</p><ul><li>如何选择细分领域</li><li>最适合新手的商业模式</li><li>最值得学习的技能</li><li>如何在Y时间内赚到X金额的钱</li></ul><p>你会一直看到这些话题被反复谈论,这是有原因的。</p><p>因为它们<em>有效</em>。它们有效,是因为95%的市场都是新手。它们有效,是因为没有人会对基本功感到厌烦。</p><p>别再试图去回避写那些人们真正想学的东西。</p><p>「但是Dan,这些东西大家早就谈过了,为什么当我谈的时候他们会在意?」</p><p>我需要你把视角拉远一点。你正处在新手地狱里,所以你的大脑很容易陷入生存模式,无法清晰思考。</p><p><em>你</em>读过多少次不同的人写这些话题?<em>你</em>在意吗?</p><p>不。因为人们需要的是被反复提醒,而不是什么新东西。</p><p>一旦你确定了想写的主题,去研究5到10个谈论这个话题的账号。留意他们每周或每月重复发布的内容。留意他们都在谈论哪些相同的内容。</p><p>然后,把它变成你品牌里一个持续存在的部分。</p><p>围绕这些主题创建多份免费指南。</p><p>每天至少针对其中一个主题创作一次内容。</p><p>写短、中、长篇内容。帖子、长推、轮播图、newsletter,以及其他形式。</p><p>你需要创建出一个<em>内容的世界</em>,让人们能够想挖多深就挖多深地去了解你的品牌,但这是我们在后面的部分会谈到的东西。</p><p><strong>3 – 筛选你最喜欢的账号,找到它们最早期的内容。</strong></p><p>很有可能,你正在照抄一些大账号那些让人感觉良好的想法。</p><p>他们已经有了受众。他们已经拥有很高的基础互动率。你根本不知道,那些帖子对一个既没有权威、也没有真正投入的人来说,是否还会有效。</p><p>詹姆斯·克利尔(James Clear)可以随便写点什么就获得成千上万个赞。你不能。为什么?因为詹姆斯已经在这个领域投入了荒谬多的时间,并发布了大量的价值内容。人们只需要读他的书,就会成为他的粉丝。而你还没写过一本书,也没有那份最初让他的书获得成功的、来自博客积累起来的100万订阅者的邮件列表。</p><p>研究一下人们为了成长,当初创作了怎样的内容。看看他们最早期的帖子,一路往下翻,直到你找到某些表现明显好于其他帖子的内容。</p><p>大多数人都经历过自己的新手地狱,然后他们会有一到两个瞬间,一次性获得大量粉丝。找到那些瞬间。</p><h3 id="_2-你的内容根本没那么好" tabindex="-1">2) 你的内容根本没那么好 <a class="header-anchor" href="#_2-你的内容根本没那么好" aria-label="Permalink to &quot;2) 你的内容根本没那么好&quot;">​</a></h3><p>说实话,如果你没有增长,那就是你的内容根本没那么好。</p><p>你不能只是随便选个主题就开始写。</p><p>你需要把读者的心理纳入考量。</p><p>你需要成为一个多巴胺贩子。</p><p>你需要<em>抓住注意力,守住注意力,并交付价值。</em></p><p>大多数人以为自己正在这样做,但其实并没有。他们写完一篇帖子就直接发出去,毫无二次思考,也不去问自己这内容到底好不好。</p><p>这些事情,每一件都需要用一生去钻研。天哪,就连我自己,也需要每个月左右重新复习一遍该怎么做。</p><p>我之前写过一封关于<a href="/letters/the-most-important-skill-of-the-21st-century-only-1-use-it">互动的10条科(Koe)诫</a>的信,如果你想深入了解带案例的内容,可以去读那篇,但我会在这里列出来,方便你练习。</p><p>我强烈建议你把这些记下来。你可以下载<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>桌面应用,用<strong>Option+C</strong>打开悬浮速记,边阅读边做笔记。</p><p><strong>1) 具体数字</strong></p><p>在你的钩子或标题中使用具体的数字,比如「苹果全新的1175美元iPhone拥有这项新功能」。</p><p>例子:</p><p><img src="'+a+'" alt=""></p><p>这有效,是因为它起到了一种模式中断的作用(附带的权威感也有帮助)。</p><p><strong>2) 模式中断</strong></p><p>模式中断,就是能把人们从他们正常、被条件反射训练出来的模式中打断出来的东西。</p><p>在社交媒体上,人们滑动浏览的大多是无聊的文字和图片。你需要做点不一样的事情,让他们停下滑动的手指。</p><p><strong>3) 负面偏好</strong></p><p>人类大脑天生就倾向于记住并关注负面信息。</p><p>这不意味着你需要变得消极,而是意味着你应该把部分内容以负面的角度来呈现(内容本身仍可以是积极的)。</p><p>「你将会成就伟大的事业。」</p><p>相比之下:</p><p>「你将再也不会跌到人生的最低谷。」</p><p>第二句要强劲得多。</p><p><strong>4) 目标点名</strong></p><p>这个很简单,直接点名你正在对谁说话。</p><ul><li>如果你现在二十多岁……</li><li>呼叫所有创作者、教练和自由职业者!</li><li>父亲是全人类的一份礼物……</li></ul><p>即便你的受众并不属于你点名的那个特定群体,这样的表达仍能让他们「选边站」,并把自己拿来跟你所说的内容作比较。</p><p><strong>5) 问题点名</strong></p><p>我们已经谈过这一点,但作为一个重要的提醒:</p><p>从痛点开始。</p><p><strong>6) 潜在利益</strong></p><p>你能为读者回答的最重要的问题之一,就是「这对我有什么好处?」</p><p>如果你在读完自己的内容后问自己这个问题,大多数人会发现,自己的内容缺乏任何实实在在的价值。你有一个很酷的想法,但人们并不在乎它。</p><p>重新训练你的大脑,让它以问题和利益的方式去思考。</p><p>从问题开始,再用一个利益点暗示出一个令人向往的转变。</p><p><strong>7) 社会认同</strong></p><p>当你展示自己的成果、经验或资历时，人们会认为你知道一些他们不知道的东西，他们就会想继续阅读或关注你。</p><p>贾斯汀·韦尔什（Justin Welsh）在这方面做得很好，而且不会显得自负：</p><p><img src="'+l+'" alt=""></p><p>谈谈你的成果。</p><p>AI 无法与你的成果竞争。</p><p>无论你是完成了一章书稿的作家，还是减了20磅的健身狂人，都要分享你的经验。我分享的是商业截图，因为那是我手头有的，但在生产力、健康、关系或整个自我提升领域都有大量的例子。数字不仅仅是钱。</p><p><strong>8) 自信与信念</strong></p><p>这是我最喜欢的一点，因为很多人拒绝对自己的观点抱有信念。如果你能在心中调和“坚定的信念，但松散地持有”这句话，那么脱颖而出就变得相当容易。</p><ul><li>消除暗示不确定性的词语</li><li>尽可能用绝对的方式说话</li><li>夸大你的观点以增加能量感</li></ul><p>当然，不要为了博取互动而滥用这些手法。</p><p>不要这样说：</p><p><em>“如果一些人能培养自己的技能，可能会是明智的。”</em></p><p>要这样说：</p><p><em>“地球上每个人都必须培养自己的技能，这是至关重要的。”</em></p><p>这里有一个很好的例子：</p><p><img src="'+o+'" alt=""></p><p>我大约在5年前写了这篇帖子。</p><p>那是我作为新手时第一篇给我带来近600个关注者的帖子。</p><p>正因如此，我一直反复谈论它，把它做成了一个线程，然后又做成了一个YouTube视频（两年后，我在起步阶段专注于一个平台），这是我频道上观看次数最多的视频。</p><p>我们会在后面的要点中讨论如何制造噪音并加倍押注于信号。</p><p><strong>9) 节奏、冲击力与可读性</strong></p><p>开头要简短，直击要点。</p><p>然后，就像这样，继续展开你的想法。</p><ul><li>使用换行</li><li>人们喜欢要点列表</li><li>你可以尽情发挥创意</li></ul><p>你注意到我是如何引导你往下阅读的吗？</p><p>我是如何开头简短、让你保持兴趣，并给出一点价值暗示的？</p><p>甚至这个要点列表也是按从最短到最长排列的。</p><p><strong>10) 警告与警示</strong></p><p>读读这篇帖子：</p><p><img src="'+i+'" alt=""></p><p>我一开始就警告人们注意一个陷阱。然后告诉他们原因。</p><p>这是一种撰写吸引人内容的绝佳方式，因为<em>每一个主题</em>都有一长串人们可能陷入的陷阱。如果你能识别出这些陷阱是什么，你就有了一份很棒的内容清单可以写。</p><p>你不需要一次用上全部10条“科诫”（Koemmandments），但我强烈建议你在写作时把这份清单打开。在你点击发送之前，确保短内容至少用到2条，长内容用到更多。</p><p>顺便说一句，我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《2小时写作者》（2 Hour Writer）</a>中谈到了所有这些内容。</p><h3 id="_3-从辅助轮开始" tabindex="-1">3) 从辅助轮开始 <a class="header-anchor" href="#_3-从辅助轮开始" aria-label="Permalink to &quot;3) 从辅助轮开始&quot;">​</a></h3><p>大多数人没有想法问题，他们有的是结构问题。</p><p>因为事情是这样的：</p><p>任何想法都能爆火，<em>前提是</em>你用正确的方式去构建它。</p><p>产生想法并不难。到目前为止，你在这份通讯中已经路过了至少50个可以拿去用的想法。</p><p>问题是，你不知道如何构建它们。</p><p>你还没有<em>训练自己的思维，以一种有影响力的方式娴熟地表达想法。</em></p><p>一旦你做到这一点，你就能把最糟糕的想法也变成人们无法停止阅读、观看或收听的东西。</p><p>就像任何其他技能一样，你需要从辅助轮开始。以下是你要做的：</p><p><strong>1) 建立一个素材库（swipe file）。</strong></p><p>如果你想成为一个创作者，你需要把手指按在市场的脉搏上。</p><p>你需要以研究者而非消费者的身份浏览社交媒体。</p><p>每当你看到一个让你想“天啊，我真希望是我写的”的爆款想法时，把它保存下来。将链接复制到Kortex的采集功能中，通过输入“@”把它整理进一个“素材库”文档。</p><p>把你的品牌想象成你所喜爱的想法、对你影响最大的想法，以及你想纳入你品牌之下的想法的融合体。</p><p>现在，你可以把这些想法用作灵感，但这不是全部重点。</p><p>你保存这些内容片段是为了模仿其结构。</p><p>我们以前面那篇帖子为例：</p><p><img src="'+s+'" alt=""></p><p>你可以看到一个清晰的<em>结构：</em></p><ul><li>一个带有理想结果和具体数字的宽泛钩子</li><li>要点列表中5个夸张且两极化的步骤</li><li>回应反对意见“可是我不能完全消失！我有朋友和家人！！”的额外背景说明</li><li>将一切串联起来的最后一句话</li></ul><p>所以，如果我从一本随便的书里得到一个不同的想法，比如“冥想是给大脑跑步”，我可以把它变成一个全新的东西：</p><p><em>如何在60秒内清空你的思绪：</em></p><ul><li><em>把自己锁在一个房间里</em></li><li><em>坐在角落里</em></li><li><em>深深地呼吸进你的腹部</em></li><li><em>用所有感官去“感受”呼吸</em></li><li><em>重复一分钟</em></li></ul><p><em>每当你分心时，把注意力重新集中到呼吸上。</em></p><p><em>“冥想冲刺”是你快速获得平静的方式。</em></p><p>如果你想更有创意一点，可以用上面的10条“科诫”来更换钩子，让它更多地塑造这篇帖子。</p><p>我可以不用“如何在60秒内清空你的思绪”，而是聚焦于一个痛点、一个统计数据、一个目标群体的点名，或者从负面角度切入，比如“如何在60秒内摧毁负面想法”。</p><p>是的，这需要你思考并与这个想法坐在一起琢磨。</p><p>这里的目标是反复练习，直到它变成第二本能。你开始用一种有说服力的方式给你妈妈发短信。你开始用一种人们愿意倾听的方式说话。这样做的好处远远超出了获得几个关注者。</p><p>最后，不要只对推文这样做。你可以研究长视频、短视频，或任何其他与你想创作的内容类型相关的东西。</p><p>如果你想要一个包含77个帖子模板的素材库，这是<a href="https://app.kortex.co/public/document/47b0dbfc-45df-43ae-802e-45b7eadd87e9" target="_blank" rel="noreferrer">我的创意博物馆</a>。</p><p><strong>2) 研究写作框架。</strong></p><p>当我刚开始写作时，框架简直是救命稻草。</p><p>我读了《广告狂想》（Ca$hvertising）这本书，学到了像AIDA（注意、兴趣、欲望、行动）这样的基础框架。</p><p>随着我在文案写作上钻研得更深，我了解到用于短篇推广的PAS框架，以及用于长篇销售信的PASTOR框架。</p><p>可以肯定地说，通过在写作中使用这些框架，我不仅能写得更快，还能感到自信，觉得自己写出的内容既抓人眼球又具有说服力。</p><p>除了你的内容素材库，<em>还要研究5-10个文案写作框架。</em></p><p>如果你愿意，可以用ChatGPT（或者下个月的Kortex AI）来做这件事。</p><p>或者，如果你想要另一个模板来继续用有用的笔记填满你的第二大脑，这里有一份关于<a href="https://app.kortex.co/public/document/bec7fcec-d76c-4d00-8669-37f53892fead" target="_blank" rel="noreferrer">痛点与过程框架（Pain &amp; Process framework）</a>的解释。</p><p><strong>3) 在写作时把它们打开。</strong></p><p>我说“写作”，但这适用于所有类型的内容。</p><p>如果你先写好你的短视频、TikTok或YouTube视频的脚本，你就能在表达上获得实实在在的掌控力。你可以<em>看到</em>钩子、句子、想法，并像拼乐高一样把它们挪来挪去，直到它们变得漂亮。不要作为新手盲目地投入内容创作。</p><ul><li>一整周持续捕捉想法</li><li>每周抽出2-3天，每次1-2小时坐下来写</li><li>打开Kortex或其他写作/笔记软件</li><li>粘贴进你的内容框架</li><li>在旁边的窗格中打开它们</li><li>写出你的想法，并参照这些框架</li></ul><p>你不是在抄袭别人的想法。<em>你是在模仿那些让它们表现出色的结构。</em></p><h3 id="_4-没有人知道你是谁" tabindex="-1">4) 没有人知道你是谁 <a class="header-anchor" href="#_4-没有人知道你是谁" aria-label="Permalink to &quot;4) 没有人知道你是谁&quot;">​</a></h3><p>你有很棒的内容。</p><p>你知道你的想法很有冲击力。</p><p>你每天都在写，但你每天最多也只能获得几个关注者。</p><p>问题出在哪里？</p><p><em>没有人知道你是谁。</em></p><p>你只是在等待你的主宰和救世主——算法，把你的帖子送上月球，但这不会发生。即便它会发生，你也应该表现得好像它不会发生一样。你的增长掌握在<em>你自己</em>手中。这在<em>你的控制之内……</em>如果你知道自己在做什么的话。</p><p>你看，内容只是社交媒体方程式中一个<em>很小的</em>部分。尤其是作为新手的时候。</p><p>这个方程式更大的部分是：</p><ul><li>认识并喜欢你的人数（因为他们更有可能分享和参与你的帖子）</li><li>看到你帖子的人数（因为作为新手几乎没有人会看到）</li><li>你与那些正在崛起的人建立的友谊质量（因为他们在成长时会把你也拉上去）</li></ul><p>如果你有500个关注者，被一个拥有50万关注者的人转发了，你的受众现在就是50万500人。</p><p>这就是人们如何用小规模受众赚取数万美元的方式。<em>他们知道如何建立人脉关系。他们知道如何让自己的内容被看到，</em><em><strong>超越</strong></em><em>他们自己的受众范围。</em></p><p>新手认为他们受限于自己的关注者数量，认为算法就是他们成长的方式。</p><p>专家们知道，他们可以接触到自己的关注者和自己人脉网络的关注者。他们写一篇他们知道会带来关注者或销售的帖子，然后让10-15个人分享它。这不是他们每天都做的事情。这是有策略的。他们积累善意，并在时机对的时候做正确的事。</p><p>萨希尔·布鲁姆（Sahil Bloom）就是一个值得关注、目前正在这样做的人。他的新书<a href="https://www.amazon.com/gp/product/059372318X?tag=randohouseinc7986-20" target="_blank" rel="noreferrer">《五种财富类型》（The 5 Types Of Wealth）</a>现已开放预订（顺便说一句，这本书轻轻松松就会成为畲销书，不是因为他有庞大的受众，而是因为他很聪明）。他日夜工作，想让尽可能多的人拿到他的书。他至少给X（推特）上的50个人寄送了免费样书，为他们标记好可能会爆火的页面让他们发帖，并在这些帖子下评论附上书的链接。他有100万关注者，但如果要我猜的话，这些帖子已经被1亿人看到过。</p><p>我扯远了。</p><p>你能做什么？</p><p><strong>1) 把自己融入一个圈子。</strong></p><p>最基本的社交媒体建议就是“多回复大账号”。</p><p>这个方法有效，也很重要，但大多数人不知道自己为什么要这样做，除了希望在回复中获得一些曝光，指望其中一些人会关注他们。</p><p>实际上，你在做的是这几件事：</p><ul><li>写出<em>有质量</em>的回复（不是“很棒的帖子！”或用ChatGPT重复对方说过的话），这样人们才有理由去看你的主页并关注你。再说一次，10条“科诫”。</li><li>在一个圈子的人群中变得广为人知。如果我想打入某个社交媒体圈子，比如创业圈，我会简单地回复该领域10个优秀账号的帖子，加入价值和个人经验。这个领域里的<em>消费者</em>会逐渐习惯你的面孔，在见得多了之后关注你，而不是在你第一次回复之后。</li><li>播种人脉连接。你在某个特定细分领域群体中回复和私信的人越多，你私信他们，或者他们私信你，就变得越容易。他们会更多地与你的帖子互动，并给你带来机会。</li></ul><p>有策略地回复。</p><p><strong>2) 练习不带需求感的社交。</strong></p><p>很遗憾这需要被教导，但确实如此。</p><p>人们不再在日常环境中学习社交技能了。</p><p>人们害怕给别人发私信，就像害怕在街上跟一个陌生人打招呼一样。</p><p>实际上，这就像<em>找到一个共同的兴趣</em>那么简单。</p><p><img src="'+n+'" alt=""></p><p><img src="'+m+'" alt=""></p><p>就是这么简单，真的。</p><p>猜猜我在他分享的那个帖子下做了什么？我转发了它。因为我有了一个新朋友，而他也够聪明，知道要把它发给我。</p><p>这里还有一份 <a href="https://app.kortex.co/public/document/e5b5d206-0874-4637-9201-6cc0d6b2f583" target="_blank" rel="noreferrer">Kortex 文档</a>，里面有7个不显得急切的社交步骤，如果你想把它加到你的工作区里。</p><p>针对他们的内容发个赞美或提个问题。聊一会儿。然后这样做：</p><p><strong>3）每周计划发一篇战略性的帖子。</strong></p><p>如果你只是在发内容，你不会增长。</p><p>就是这么简单直白。</p><p>而如果你确实增长了，算法最终会变化，到那时你就会在没有支持网络的大海里漂着。</p><p>你需要每周进行对话。你需要写出能给这些对话增添价值的帖子，并把它们分享给那些人。</p><h3 id="_5-你需要一个产品" tabindex="-1">5）你需要一个产品 <a class="header-anchor" href="#_5-你需要一个产品" aria-label="Permalink to &quot;5）你需要一个产品&quot;">​</a></h3><p>大多数创作者一直等到达到某个想象中的粉丝数量才去变现，结果却发现没人买。</p><p>或者，他们以为自己能从平台变现（比如 YouTube）里赚到不错的收入，直到撞上瓶颈，播放量骤降长达两个月。</p><p>重点是，如果你想掌控自己的收入，你需要销售一个产品或服务。</p><p>这样做能带来几个好处：</p><p><strong>1）人们开始把你视为权威。</strong></p><p>大多数创作者积累的受众根本不在乎他们。</p><p>他们没意识到，光靠内容不足以与人建立深层连接。人们需要<em>对你有所投入</em>，才会更加关注你。</p><p>人们上社交媒体不是为了学习和养成新习惯。他们买产品才是为了这个。而一旦你改变了他们的习惯，或者改变了他们的生活，他们对你的评价会高得多。</p><p>许多创作者停滞不前，仅仅是因为他们的受众只停留在表面层次。</p><p><strong>2）它为你的内容提供了一个框架和动力。</strong></p><p>如果你不知道该写什么，就写一个能解决与你所售产品或服务相关痛点的主题。就这么简单。</p><p>除此之外，很多人没有继续创作内容的<em>理由</em>，因为没有即时的回报。</p><p>如果你有产品或服务，你至少有<em>可能</em>从中赚到一些钱。你就能把精力集中在能带来结果的事情上。</p><p><strong>3）它让试错变得更可容忍。</strong></p><p>如果有什么行不通，你<em>知道</em>它行不通。</p><p>你没有获得点击。你没有获得销量。</p><p>如果你没有获得点击，就围绕更多痛点写内容，并用不显急切的社交方式把它传播给更多人。</p><p>如果你没有获得销量，就去研究要约创建（offer creation）和文案写作，以提升转化率。</p><p>如果你不知道从产品或服务方面从何入手，我在<a href="https://stan.store/thedankoe/p/the-oneperson-business-launchpad--your-first-5k" target="_blank" rel="noreferrer">一人企业发射台（One-Person Business Launchpad）</a>中展示了如何搭建一个“MVO”。</p><h3 id="_6-构建一个世界-而不是一个漏斗" tabindex="-1">6）构建一个世界，而不是一个漏斗 <a class="header-anchor" href="#_6-构建一个世界-而不是一个漏斗" aria-label="Permalink to &quot;6）构建一个世界，而不是一个漏斗&quot;">​</a></h3><p>倒计时器和虚假稀缺感的时代已经过去了。</p><p>如今，创作者们构建的是世界，而不是漏斗——尽管一个简单的邮件通讯加落地页也可以算作一个漏斗。在这种情况下，你是在构建一个由许多小型漏斗组成的世界。</p><p>普通消费者一开始并不会信任别人。你需要时间的积累，也需要足够的价值让他们去探索，才能获得他们的信任。</p><p>你需要构建一个小规模的漫威电影宇宙。你需要打造电影、玩偶手办和让人能一口气刷完的传说故事。</p><p>换句话说，你需要：</p><ul><li>短内容（X、LinkedIn、Instagram、Threads 或 TikTok）</li><li>长内容（邮件通讯、播客或 YouTube）</li><li>免费指南（电子书、模板、视频培训）</li><li>低价产品（课程、模板、训练营）</li><li>高价产品（教练服务、自由职业、咨询）</li></ul><p>先从一种短内容和一种长内容开始。我建议把 X、LinkedIn 或 Threads 与邮件通讯结合起来。然后，你可以把这些邮件通讯当作 YouTube 脚本使用，把你的短帖跨平台发布到所有其他平台，并把其中最好的用作 Reel 或 TikTok 的脚本。</p><p>然后，一旦你建立起足够的分发渠道和现金流，你就有资源去转向像电商或软件这样的方向。</p><p>社交帖子就是新时代的 MVP（最小可行产品）。</p><p>多发一些帖子。把最好的变成邮件通讯。把它们跨平台分发到各处。把最好中的最好变成一个数字产品。不断打磨它，直到销量变高。把这个系统变成一个软件，或者用一个实体产品来补充它。</p><h3 id="_7-制造噪音-加倍押注信号" tabindex="-1">7）制造噪音，加倍押注信号 <a class="header-anchor" href="#_7-制造噪音-加倍押注信号" aria-label="Permalink to &quot;7）制造噪音，加倍押注信号&quot;">​</a></h3><p>最后一个反对意见：</p><p>“但 Dan，我想以真实的方式写出我的想法。这整个社交媒体的东西感觉太没灵魂、太模板化了。”</p><p>我同意。</p><p>但要处理第一部分，模板和框架并不会让你变得不真实。创造力在约束中蓬勃发展，而一个框架能让你把真实的想法用别人在意的方式表达出来。</p><p>如果你想不顾别人的想法、纯粹地做“真实的自己”，那很好，但祝你好运，能不能把这维持成一种能付你薪水的生活方式就另说了。不是说钱是万能的终极目标，但它确实重要，而且它的邪恶程度取决于掌握它的人。</p><p>至于第二部分，你<em>可以</em>写任何你想写的东西。</p><p>你不必陷入只写那些在算法里表现好的内容的陷阱。</p><p>你<em>应该</em>给两者都留出空间。既有你知道能让更多人看到你的内容，也有你认为那些人会喜欢的内容。</p><p>但如果人们没有先发现你，他们就没有机会看到你其他更深层的想法。</p><p>所以，尽情去制造噪音吧。</p><p>写任何你内心渴望的想法。</p><p>留意人们产生共鸣的那些想法。</p><p>那些能带来稍多一点互动、私信或粉丝的想法。</p><p>然后，把它们纳入你内容策略中持续存在的一部分。</p><p>你不需要选择一个细分领域。你需要不断尝试各种想法，直到人们告诉你，什么细分领域最适合你和受众之间的关系。</p><p>如果你想更多了解我“你就是细分领域”的理念，这里有一篇之前写的信。</p><p>感谢阅读。</p><p>——Dan</p><hr><p><a href="/en/letters/how-to-escape-beginner-hell-as-a-creator">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',285))])}const E=h(b,[["render",k]]);export{O as __pageData,E as default};
